"""Generate release/<board>/README.md (design notes, verification, BOM, assembly, bring-up) from the board spec and verification results."""
import sys, os, json, importlib
HERE = os.path.dirname(os.path.abspath(__file__)); sys.path.insert(0, HERE)
NOTES = {
 "seeti": dict(
  desc="Clip-on pressure-cooker whistle counter: electret microphone, band-pass amplifier, ATmega328P-AU, buzzer, LED, 2 x AAA.",
  circuit=["**Power:** 2 x AAA (3.0 V fresh, about 2.0 V end of life) -> slide switch SW1 -> AO3401A P-MOSFET Q2 (drain = battery side, source = load, gate = GND) = reverse-battery protection with about 50 mV drop. **Clock:** the ATmega328P is specified for 8 MHz only at 2.7 V and above (1.8 V is allowed up to 4 MHz), and two AAA cells fall below 2.7 V about half-way through their life, so the firmware must switch to 4 MHz at boot (`clock_prescale_set(clock_div_2)`, F_CPU = 4 MHz; ADC clock and the 8 kHz audio sampling still work). Check the speed-grade graph in the current datasheet.",
           "**Microphone amplifier:** electret capsule biased through R1 2.2 k; AC-coupled (C5 1 uF) into an MCP6001 (rail-to-rail, 1 MHz GBW) non-inverting stage biased at VCC/2 (R2/R3 100 k + C7 10 uF so the feedback return is low impedance). Gain 1 + R8/R9 = 1 + 33k/1k = 34 (SPICE 32.9x at 2.8 kHz); C6 220 nF in the feedback return gives a high-pass at 1/(2 pi R9 C6) = 720 Hz which rejects 100 Hz mains hum and cooking noise before the whistle tone (about 2.8 kHz, to be measured). The amplifier stays flat to about 26 kHz, so **R10 1k + C9 22 nF form a 7.2 kHz first-order anti-alias filter** in front of the ADC; with 16 kS/s sampling this is only a mild filter (about 8 dB at 16 kHz): a known limitation.",
           "**Digital:** ADC0 reads the amplifier; buzzer through MMBT3904 with flyback diode; button on PD2, LED on PD7; ISP header and a 4-pin UART header (115200 baud debug); reset pulled up by 10 k."],
  sims=["sim/seeti_amp_results.txt", "sim/seeti_headroom.txt"],
  power="Run current estimate: MCU at 4 MHz and 3 V about 2 mA, amplifier 0.1 mA, microphone bias up to 0.5 mA, LED 1 mA when lit: about 3.6 mA -> 2 x AAA (about 1000 mAh to 2.0 V) gives roughly 250 h of cooking time (estimate, not measured). Add sleep modes in firmware if the unit will stay switched on.",
  bringup=["Insert 2 x AAA with switch OFF; measure BAT_P to GND (J1 pins) = 2.8-3.2 V.", "Switch ON: TP1 (+3V0) = battery minus about 0.05 V; no heating.", "VMID (R2/R3 junction) = VCC/2 +-0.05 V; TP3 (MIC_OUT) = VCC/2 +-0.1 V with no sound (same DC at the ADC pin through R10).", "Flash firmware over ISP (J2): `avrdude -p m328p -c usbasp -U lfuse:w:0xE2:m -U hfuse:w:0xD9:m -U efuse:w:0xFE:m` (internal 8 MHz RC, CKDIV8 off, brown-out 1.8 V; the firmware then divides the clock to 4 MHz).", "Play a 2.8 kHz tone from a phone at 10 cm: TP3 swings about +-100 mV peak and the firmware counts whistles."]),
 "bijli": dict(
  desc="Optical electricity-meter pulse reader: USB-C 5 V powered ATmega328P-AU, sensor-head connector (phototransistor), TM1637 4-digit display connector, reset button, LED.",
  circuit=["**Power:** USB-C power-only sink: CC1/CC2 each 5.1 k to GND (R1, R2) so a charger delivers 5 V; 0.5 A PTC fuse F1 (1206) then +5V; SMAJ5.0A TVS D3 on VBUS clamps spikes; 10 uF + 100 nF decoupling.",
           "**Sensor head:** phototransistor between SIG_H and GND, 10 k pull-up R4 to +5V, 100 ohm series R6 + 100 nF C5 on SIG; SIG falls when the meter LED lights. Firmware adapts its threshold to the observed minimum/maximum (swing must be >= 0.2 V).",
           "**MCU/display:** ATmega328P-AU at the internal 8 MHz RC, ADC0 reads SIG, TM1637 display module on JST-PH J4 (GND, +5V, DIO, CLK), reset-bill button on PD2, LED on PD7, ISP header."],
  sims=["sim/bijli_head_results.md"],
  power="MCU 5 V 8 MHz about 6 mA + display 10-30 mA + LED: under 50 mA, far below the 500 mA default USB limit and the 0.5 A PTC.",
  bringup=["Plug a 5 V charger: VBUS (TP at J1/F1) = 5.0 V; +5V (TP1) = 4.9-5.0 V.", "SIG with head disconnected = 5 V (pull-up); with the phototransistor in the dark about 4.9 V; under a lit meter LED a drop of at least 0.5 V.", "Flash over ISP: `avrdude -p m328p -c usbasp -U lfuse:w:0xE2:m -U hfuse:w:0xD9:m -U efuse:w:0xFD:m` (internal 8 MHz, brown-out 2.7 V; USB supply is 5 V).", "Hold the head over a 1 Hz test LED: display counts one pulse per second."]),
 "rain": dict(
  desc="Rain Alert Bell indoor unit: 3 x AA, ATmega328P-AU, loud buzzer, mute button, pulsed rain-plate interface with TVS protection.",
  circuit=["**Power:** 3 x AA (4.5 V fresh) -> slide switch -> AO3401A reverse-polarity PMOS -> +4V5. ATmega328P at 4.5 V, 8 MHz internal RC.",
           "**Rain plate interface:** DRV (PD5) is driven high for about 2-5 ms per reading through R1 1 k; the plate resistance (wet 1 k - 150 k) forms a divider with R2 100 k to GND at SENSE (ADC0); R3 1 k + C5 2.2 nF filter; D3/D4 bidirectional 5 V TVS diodes on both cable lines. Because the plate is powered only during measurement there is no DC across the wet gold plate: far less electrolytic corrosion.",
           "**Sleep:** firmware sleeps in power-down with a 1 s watchdog wake; average current is tens of microamperes plus about 5 mA x 5 ms per second."],
  sims=["sim/rain_sense_results.md"],
  power="Awake 5 ms per second at about 5 mA (average 25 uA) + power-down 6 uA + regulator-free supply: about 30 uA average -> 2500 mAh AA cells would last years; battery self-discharge dominates (alarm current about 30 mA for the buzzer while ringing).",
  bringup=["Insert 3 x AA, switch ON: TP1 = 4.2-4.6 V.", "Connect the plate: SENSE (TP3) between readings = 0 V; during a reading about 0.2 V with a dry plate.", "Wet the plate with a drop of water: SENSE rises to > 1.7 V during the 5 ms pulse; after 3 s of continuous wet readings the buzzer sounds.", "Flash over ISP with fuses lfuse 0xE2, hfuse 0xD9, efuse 0xFD (8 MHz internal, BOD 2.7 V: the unit resets cleanly when the batteries fall below 2.7 V, which is the 8 MHz limit)."]),
 "rainplate": dict(desc="Rain plate: two interleaved gold (ENIG) comb electrodes, 44 fingers, mounted on the terrace wall, connected by a 2-core cable to the indoor unit.",
  circuit=["Fingers 0.4 mm wide with 0.4 mm gaps over a 28 x 35 mm area; spines 0.6 mm; solder-mask opening over the whole comb so the bare gold is the sensing surface; four M3 holes; two cable pads (DRV, SENSE)."],
  sims=[], power="Passive.", bringup=["Dry plate: > 10 MOhm between DRV and SENSE; wet plate: < 150 kOhm.", "Check ENIG finish and mask opening on the delivered boards."]),
}
def gen(mod):
    B = importlib.import_module("boards." + mod).BOARD; N = NOTES[mod]; name = B["name"]; out = os.path.join(HERE, "out", mod); V = json.load(open(os.path.join(out, "verification.json")))
    W, H = B["size"]
    r = [f"# {B['title']} (rev {B.get('rev','A')})", "", N["desc"], "", f"**Status: engineering release, software-verified only (ERC on the netlist, KiCad DRC, netlist cross-check, SPICE where noted). Not yet built, not reviewed by a second engineer, not certified.**", "",
         "## Specification", f"- Board {W} x {H} mm, 2 layers, 1.6 mm FR-4, 1 oz copper, rounded corners R{B.get('corner',2.0)} mm, {len(B.get('holes',[]))} x M2.5 mounting holes, {len(B.get('fids',[]))} fiducials.",
         f"- Rules used: min track {0.2} mm (power {0.4} mm), min clearance {B.get('clr',0.2)} mm, via {0.6}/{0.3} mm, GND pour on both layers, {V.get('stitch_vias',0)} stitching vias.", "- Finish: ENIG recommended" + (" (required for the rain plate)" if mod == 'rainplate' else " (HASL lead-free acceptable)") + "; green mask, white silk; IPC class 2.",
         f"- {V['parts']} parts, {V['nets']} nets.", "", "## Circuit description"] + [f"- {c}" for c in N["circuit"]]
    for s in N["sims"]:
        p = os.path.join(HERE, s)
        if os.path.exists(p): r += ["", f"### Simulation: `{s}`", "```", open(p).read().strip(), "```"]
    r += ["", "## Power", N["power"], "", "## Verification", "| Check | Result |", "|---|---|", f"| Electrical rule check on the netlist (own ERC: unconnected pins, single-pin nets, output conflicts, unpowered supplies, symbol/footprint pin match) | {len(V['erc_errors'])} errors, {len(V['erc_warnings'])} warnings |",
          f"| KiCad DRC | {V['drc_errors']} errors, {V['drc_warnings']} warnings; unconnected pads: {V['unconnected']} |", f"| Schematic netlist equals PCB netlist | {'yes' if V['netlist_match'] else 'NO: ' + str(V['netlist_mismatch'])} |", f"| Router failures | {len(V['route_failures'])} |", f"| 3D STEP export | {'yes' if V.get('step') else 'no'} |", f"| Independent Gerber parse (gerbonara): layers parsed, outline size equals the design | {V.get('gerber_independent_check', {}).get('layers', '?')} layers, outline {V.get('gerber_independent_check', {}).get('outline_mm')} mm, {'match' if V.get('gerber_independent_check', {}).get('size_ok') else 'CHECK'} |"]
    if V.get("drc_waived"): r += ["", "Waived DRC items (by design): " + "; ".join(f"{k} x{v}" for k, v in V["drc_waived"].items())]
    if V.get("drc"): r += ["", "DRC breakdown: " + ", ".join(f"{k} x{v}" for k, v in sorted(V["drc"].items())) if V["drc"] else ""]
    if os.path.exists(os.path.join(out, "enclosure.json")): e = json.load(open(os.path.join(out, "enclosure.json"))); r += ["", f"Enclosure (prototype shell for 3D printing): outer {e['outer'][0]} x {e['outer'][1]} x {e['outer'][2]} mm, collision/opening check: " + ("pass" if not e["issues"] else "; ".join(e["issues"]))]
    r += ["", "## Bill of materials", "| Ref | Value | Footprint | Manufacturer part | LCSC # | LCSC status |", "|---|---|---|---|---|---|"]
    for p in B["parts"]: r.append(f"| {p['ref']} | {p['value']} | {p['fp'].split(':')[1]} | {p.get('mpn','')} | {p.get('lcsc','')} | {p.get('lcsc_status','') or ''} |")
    r += ["", "`verified` = LCSC number confirmed by web search on 2026-10-31/11-01; `memory` = from my recollection, **check on lcsc.com before ordering**; empty = no number chosen (through-hole connectors, switches, buzzer, test points: hand-assembled or chosen by the buyer). `*_JLC_BOM.csv` / `*_JLC_CPL.csv` list only the parts with an LCSC number; JLCPCB rotation corrections (CPL) must be checked in their viewer.", "",
          "## Assembly notes", "- Reflow (JLCPCB SMT): all SMD parts with an LCSC number. Hand-solder: JST connectors, pin headers, buzzer, switches, test points as listed in the BOM. Fiducials and mounting holes are in the Gerbers.", "- Polarity: LED cathode toward GND (silk marks), electrolytic none, diode D2 cathode to +V, Q2 orientation as footprint (SOT-23 pin 1 = gate).", "- Programming: ISP header J2 (pin 1 = MISO, square pad). Flash the matching image from `utility10/firmware/release/`: Seeti Counter `4MHz/seeti_prod.hex` (production firmware: timer-triggered 16 kS/s ADC, scan mode to find the real whistle frequency, battery check), Rain Alert `8MHz/rain_alert.hex`, Bijli Meter Reader `8MHz/bijli_meter.hex` (demo-grade firmware, to be hardened).", "",
          "## Bring-up and test", *[f"{i}. {t}" for i, t in enumerate(N["bringup"], 1)], "",
          "## Files", f"`{name}.kicad_pcb/.kicad_sch/.kicad_pro` (KiCad 7), `gerbers/` (Gerber X2 + drill, zip), `{name}_JLC_BOM.csv`, `{name}_JLC_CPL.csv`, `{name}_BOM_full.csv`, `{name}.step`, `{name}_schematic.pdf`, `{name}_assembly_top.pdf`, `{name}_copper.pdf`, `{name}_enclosure_base.stl/_lid.stl`.", "",
          "## Known limits and review checklist", "- Layout was produced by a custom router and software placement; a human layout review (analog routing, ground returns, creepage, connector mechanics, silkscreen) is still required.", "- Not verified: EMC, ESD (apart from TVS parts where fitted), thermal, real component tolerances, supplier stock/price, assembly house design-for-manufacture check (run JLCPCB's DFM check on the Gerbers).", "- Firmware thresholds are placeholders to be calibrated on prototypes.", ""]
    path = os.path.join(out, "README.md"); open(path, "w").write("\n".join(r)); return path
if __name__ == "__main__": print(gen(sys.argv[1]))
